('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','offer-builder','Offer · Commercial grounds maintenance','[]'::jsonb,'{"what": "Commercial maintenance offer", "context_summary": "Evergreen Grounds"}'::jsonb,'{"headline": "Commercial grounds maintenance that never makes you chase us", "who_its_for": "Strata councils and property managers tired of no-shows and surprise invoices.", "outcome": "Your property looks sharp every week on a fixed monthly fee, with photos after every visit so you never wonder if we showed up.", "scope_included": ["Weekly mow, edge and trim to a set standard", "Seasonal cleanups and bed care", "Photo report after every visit", "One named crew lead as your point of contact"], "scope_excluded": ["Tree removal over 20 feet", "Irrigation repairs (quoted separately)", "Snow and ice (seasonal add-on)"], "pricing": {"recommended": "Tiered monthly, 12-month term", "rationale": "Recurring monthly keeps cash predictable for both sides, and a 12-month term lets us hold the price.", "tiers": [{"name": "Essential", "price": "$1,200/mo", "for": "Smaller strata, basic upkeep", "includes_short": "Weekly maintenance + seasonal cleanups"}, {"name": "Standard", "price": "$1,900/mo", "for": "Most commercial sites", "includes_short": "Essential + bed care + photo reports + named lead"}, {"name": "Premium", "price": "$2,800/mo", "for": "High-visibility properties", "includes_short": "Standard + priority scheduling + quarterly walkthrough"}], "payment_terms": "Monthly, net 15, auto-renew with 60 days notice"}, "objection_handlers": [{"objection": "The last company kept missing visits", "response": "Every visit ends with a timestamped photo report, so you see it got done without checking."}, {"objection": "Your price is higher than the quote we got", "response": "The cheaper quote usually leaves out cleanups and reporting, then bills them as extras. This is all-in and fixed."}], "positioning_1liner": "The grounds crew that proves it showed up."}'::jsonb),
('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','rocks-tracker','Rocks · Q1 (Jan to Mar)','[]'::jsonb,'{"quarter": "Q1", "context_summary": "Evergreen Grounds"}'::jsonb,'{"quarter_label": "Q1 (Jan to Mar)", "theme": "Get a crew lead running the main crew without you, before the March bids", "summary": "One quarter, one real shift: prove the standard holds without the owner on site, so a second crew is a staffing exercise, not a gamble.", "company_rocks": [{"title": "Marcus running the main crew without the owner on site", "owner": "Alex", "category": "team", "why_this": "The whole second-crew decision rests on whether the standard holds without you.", "definition_of_done": ["Owner off the main crew five days a week", "Renewal rate held through the quarter", "Two client check-ins came back positive"], "weekly_milestones": [{"week": "1-2", "milestone": "Promote Marcus, set expectations, shadow once"}, {"week": "3-6", "milestone": "Owner off site two days, then four"}, {"week": "7-12", "milestone": "Owner fully off the crew, spot-checks only"}], "traps": ["Stepping back in the moment something goes slightly wrong", "Not telling the crew the standard is now Marcus''s call"]}, {"title": "Win at least one of the two March strata contracts", "owner": "Alex", "category": "revenue", "why_this": "It is the work that justifies a second crew.", "definition_of_done": ["Both bids submitted by end of February", "At least one signed"], "weekly_milestones": [{"week": "1-4", "milestone": "Confirm scope and site lists"}, {"week": "5-8", "milestone": "Price and submit both bids"}, {"week": "9-12", "milestone": "Follow up and close"}], "traps": ["Pricing to win instead of to carry the work"]}], "individual_rocks": [{"title": "Write the three main routes as SOPs", "owner": "Marcus", "category": "systems", "why_this": "A second crew can only match the standard if it is written down.", "definition_of_done": ["Three routes documented", "Crew ran from them for two weeks"], "weekly_milestones": [{"week": "1-6", "milestone": "Draft and test the first route"}, {"week": "7-12", "milestone": "Finish all three, fix what did not match"}], "traps": ["Writing them perfect instead of real"]}], "what_we_are_NOT_doing": ["Buying the second truck before the bids land", "Adding residential work this quarter", "Chasing one-off installs"], "risks": ["Both strata bids go elsewhere", "Marcus does not want to lead"], "books": ["Traction (Gino Wickman)", "The Great Game of Business (Jack Stack)"]}'::jsonb),
('de900000-0000-4000-8000-000000000001','f1eb0b1f-be17-4ade-b013-e706ea825d0e','team-newsletter','Team newsletter · October 2026','[]'::jsonb,'{"period": "October 2026", "tone": "warm", "context_summary": "Evergreen Grounds"}'::jsonb,'{"subject": "Evergreen update: a strong quarter and what is next", "sections": [{"heading": "Where we are at", "body": "Revenue is up 22% and margin is up to 16%. The recurring maintenance book is carrying the business, and that is down to the standard this crew holds on every site."}, {"heading": "What is changing", "body": "Marcus is stepping up to run the main crew. The goal is simple: keep sites to the standard without me on every one, so we can take on the commercial work coming in March."}, {"heading": "What I need from you", "body": "Keep logging the day at the end of each shift, and flag anything on site that slowed you down. That is how we catch the gate-key and access problems before they cost us time."}], "sign_off": "Proud of this crew. Alex"}'::jsonb);
